//! Import backend selection.
//!
//! In wasm the SDK calls the real imports generated by wit-bindgen. On
//! native targets (plugin unit tests) the same calls go to the fakes in
//! [`crate::testing`], which mirror the generated signatures exactly.

#[cfg(target_arch = "wasm32")]
pub(crate) use crate::bindings::arcode::plugin::{editor, host, http, kv, ui, workspace};

#[cfg(not(target_arch = "wasm32"))]
pub(crate) use crate::testing::imports::{editor, host, http, kv, ui, workspace};
